-- Portable contract fixture for the GitHub source service.
CREATE TABLE repository_sources(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,binding_key TEXT NOT NULL,policy_hash TEXT NOT NULL CHECK(length(policy_hash)=64),repository TEXT NOT NULL,branch TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','syncing','current','unavailable','disconnected')),reason TEXT,version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),generation INTEGER NOT NULL DEFAULT 0 CHECK(generation>=0),last_verified_at TEXT,next_refresh_at TEXT NOT NULL,last_started_at TEXT,lease_id TEXT,lease_until TEXT,connected_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(workspace_id,project_id),UNIQUE(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id),CHECK((lease_id IS NULL AND lease_until IS NULL) OR (lease_id IS NOT NULL AND lease_until IS NOT NULL)));
CREATE INDEX idx_repository_source_refresh ON repository_sources(state,next_refresh_at,lease_until);
CREATE TABLE repository_observations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,source_id TEXT NOT NULL,generation INTEGER NOT NULL CHECK(generation>0),policy_hash TEXT NOT NULL CHECK(length(policy_hash)=64),manifest_hash TEXT NOT NULL CHECK(length(manifest_hash)=64),payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB)) BETWEEN 1 AND 524288),observed_at TEXT NOT NULL,UNIQUE(workspace_id,project_id,source_id,id),UNIQUE(source_id,policy_hash,manifest_hash),FOREIGN KEY(workspace_id,project_id,source_id) REFERENCES repository_sources(workspace_id,project_id,id));
CREATE TABLE repository_source_heads(source_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,observation_id TEXT NOT NULL,FOREIGN KEY(workspace_id,project_id,source_id,observation_id) REFERENCES repository_observations(workspace_id,project_id,source_id,id));
CREATE TABLE repository_source_events(workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence>0),source_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('connected','observed','unavailable','disconnected')),created_by TEXT REFERENCES users(id),created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,project_id,sequence),FOREIGN KEY(workspace_id,project_id,source_id) REFERENCES repository_sources(workspace_id,project_id,id));
CREATE TABLE repository_source_receipts(workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,request_id TEXT NOT NULL,source_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('connect','refresh','disconnect')),input_hash TEXT NOT NULL CHECK(length(input_hash)=64),source_version INTEGER NOT NULL CHECK(source_version>0),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,project_id,request_id),FOREIGN KEY(workspace_id,project_id,source_id) REFERENCES repository_sources(workspace_id,project_id,id));
